import{_ as e,c as i,o as l,ag as r}from"./chunks/framework.DfL_BkQ-.js";const m=JSON.parse('{"title":"Guía del permiso de grabación de pantalla (macOS)","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/screen-recording.md","filePath":"es/guide/screen-recording.md","lastUpdated":1794112334000}'),s={name:"es/guide/screen-recording.md"};function n(o,a,t,c,d,p){return l(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="guia-del-permiso-de-grabacion-de-pantalla-macos" tabindex="-1">Guía del permiso de grabación de pantalla (macOS) <a class="header-anchor" href="#guia-del-permiso-de-grabacion-de-pantalla-macos" aria-label="Permalink to &quot;Guía del permiso de grabación de pantalla (macOS)&quot;">​</a></h1><h2 id="¿por-que-nicasa-necesita-el-permiso-de-grabacion-de-pantalla" tabindex="-1">¿Por qué Nicasa necesita el permiso de grabación de pantalla? <a class="header-anchor" href="#¿por-que-nicasa-necesita-el-permiso-de-grabacion-de-pantalla" aria-label="Permalink to &quot;¿Por qué Nicasa necesita el permiso de grabación de pantalla?&quot;">​</a></h2><p>En macOS, las aplicaciones de captura de pantalla deben tener concedido el permiso de grabación de pantalla para poder leer los píxeles del monitor.</p><p>A partir de macOS 10.15 Catalina, Apple introdujo protecciones de privacidad más estrictas. Cualquier aplicación que capture el contenido de la pantalla, incluidas las capturas, debe ser aprobada explícitamente por el usuario.</p><p>Esto se aplica a todas las apps, incluidas las descargadas del Mac App Store.</p><p><strong>Sin este permiso, Nicasa no puede hacer capturas ni grabar el contenido de la pantalla.</strong></p><h2 id="como-activar-el-permiso-de-grabacion-de-pantalla" tabindex="-1">Cómo activar el permiso de grabación de pantalla <a class="header-anchor" href="#como-activar-el-permiso-de-grabacion-de-pantalla" aria-label="Permalink to &quot;Cómo activar el permiso de grabación de pantalla&quot;">​</a></h2><p>Sigue estos pasos:</p><ol><li>Abre <strong>Ajustes del Sistema</strong></li><li>Ve a <strong>Privacidad y seguridad</strong></li><li>Selecciona <strong>Grabación de pantalla</strong></li><li>Busca <strong>Nicasa</strong> en la lista y marca la casilla</li></ol><p>Si la app ya estaba en ejecución, reinicia Nicasa después de activar el permiso.</p><h2 id="si-no-aparecio-el-aviso-de-permiso" tabindex="-1">Si no apareció el aviso de permiso <a class="header-anchor" href="#si-no-aparecio-el-aviso-de-permiso" aria-label="Permalink to &quot;Si no apareció el aviso de permiso&quot;">​</a></h2><p>El diálogo de permiso suele aparecer la primera vez que la app intenta capturar la pantalla.</p><p>Si no viste el aviso, puede deberse a que:</p><ul><li>La solicitud de permiso se rechazó anteriormente</li><li>El estado del permiso está en caché en macOS</li><li>La app intentó capturar antes de que pudiera aparecer el diálogo</li></ul><p>En este caso, puede que necesites restablecer el permiso.</p><h2 id="restablecer-el-permiso-de-grabacion-de-pantalla" tabindex="-1">Restablecer el permiso de grabación de pantalla <a class="header-anchor" href="#restablecer-el-permiso-de-grabacion-de-pantalla" aria-label="Permalink to &quot;Restablecer el permiso de grabación de pantalla&quot;">​</a></h2><p>Puedes restablecer el permiso con el siguiente comando en Terminal:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tccutil</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reset</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ScreenCapture</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> com.nicasa.nue</span></span></code></pre></div><p>Después de ejecutar el comando:</p><ol><li>Reinicia Nicasa</li><li>Vuelve a activar la función de captura</li><li>macOS debería mostrar de nuevo el diálogo de permiso</li></ol><h2 id="si-el-restablecimiento-no-funciona" tabindex="-1">Si el restablecimiento no funciona <a class="header-anchor" href="#si-el-restablecimiento-no-funciona" aria-label="Permalink to &quot;Si el restablecimiento no funciona&quot;">​</a></h2><p>En raras ocasiones, macOS puede conservar un estado de permiso no válido.</p><p>Si restablecer el permiso no resuelve el problema, prueba los siguientes pasos:</p><ol><li>Cierra Nicasa</li><li>Elimina Nicasa de tu carpeta Aplicaciones</li><li>Reinstala la última versión desde el Mac App Store</li><li>Abre la app de nuevo</li><li>Cuando macOS solicite el permiso de grabación de pantalla, selecciona <strong>Permitir</strong></li></ol><p>Reinstalar la app puede forzar a macOS a recrear la entrada de permiso.</p><h2 id="solucion-manual-alternativa" tabindex="-1">Solución manual alternativa <a class="header-anchor" href="#solucion-manual-alternativa" aria-label="Permalink to &quot;Solución manual alternativa&quot;">​</a></h2><p>También puedes alternar el permiso manualmente:</p><ol><li>Abre <strong>Ajustes del Sistema</strong></li><li>Ve a <strong>Privacidad y seguridad</strong></li><li>Abre <strong>Grabación de pantalla</strong></li><li>Desmarca Nicasa y vuelve a marcarlo</li><li>Reinicia Nicasa</li></ol><h2 id="nota-de-seguridad" tabindex="-1">Nota de seguridad <a class="header-anchor" href="#nota-de-seguridad" aria-label="Permalink to &quot;Nota de seguridad&quot;">​</a></h2><p>Conceder el permiso de grabación de pantalla no permite a Nicasa controlar tu sistema.</p><p>Solo permite a la aplicación leer los píxeles de la pantalla para las funciones de captura.</p><p>Puedes revocar este permiso en cualquier momento en: <strong>Ajustes del Sistema → Privacidad y seguridad → Grabación de pantalla</strong></p>',32)])])}const g=e(s,[["render",n]]);export{m as __pageData,g as default};
